/**
 * The process setup's shared public-API cases
 * (`tests/fixtures/abi-v1/setup-cases.json`, generated by
 * `scripts/abi-v1/emit/setup_cases.py` and read by all four bindings), run
 * through the public API over fresh copies of the stub libraries.
 *
 * Each case gets a fresh image per variant it opens (its own copy of that
 * stub) and starts with no setup recorded. Without `$CHTYPES_ABI1_STUBS` every case SKIPS LOUDLY by
 * name; it never passes silently.
 */

import { chmodSync, copyFileSync, mkdtempSync, readFileSync } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { describe, expect, it, vi } from 'vitest';
import {
  ArtifactCorruptError,
  ArtifactIncompatibleError,
  type Filter,
  Format,
  InternalError,
  type Library,
  openUnverified,
  Registry,
  type Schema,
  SchemaError,
  Status,
  setup,
  UnsupportedError,
  UsageError,
} from '../../src/index.js';
import { resetSetupForTests } from '../../src/setup.js';

const STUBS_DIR = process.env.CHTYPES_ABI1_STUBS;
const stubsAvailable = typeof STUBS_DIR === 'string' && STUBS_DIR.length > 0;

const SETUP_CASES_PATH = path.resolve(import.meta.dirname, '../../../tests/fixtures/abi-v1/setup-cases.json');

interface Expect {
  readonly ok?: boolean;
  readonly class?: string;
  readonly status?: string;
  readonly ch_code?: number;
  readonly ch_name?: string;
  readonly reason?: string;
  /** On a successful open: the zone the image was set up with, read back with the document's `image_zone_probe`. */
  readonly image_zone?: string;
}

interface Step {
  readonly op: string;
  readonly timezone?: string;
  readonly variant?: string;
  readonly request?: string;
  readonly allow?: boolean;
  readonly expect: Expect;
  /** The compile and filter ops (rule r7): the names and the statement or expression they use, the body (CSV), and the `rowsPassed` a batch result must report. */
  readonly as?: string;
  readonly schema?: string;
  readonly statement?: string;
  readonly filter?: string;
  readonly expression?: string;
  readonly body?: string;
  readonly rows_passed?: number;
}

interface SetupCase {
  readonly id: string;
  readonly variant: string;
  readonly steps: readonly Step[];
  /** The bindings that cannot express the case, and why. */
  readonly not_expressible?: Readonly<Record<string, string>>;
}

const setupDoc = JSON.parse(readFileSync(SETUP_CASES_PATH, 'utf8')) as { image_zone_probe: string; cases: SetupCase[] };
const setupCases: readonly SetupCase[] = setupDoc.cases;

const CLASSES: Readonly<Record<string, abstract new (...args: never[]) => Error>> = {
  schema: SchemaError,
  unsupported: UnsupportedError,
  usage: UsageError,
  internal: InternalError,
  artifact_incompatible: ArtifactIncompatibleError,
  artifact_corrupt: ArtifactCorruptError,
};

/** `CHS_INVALID_ARGUMENT` -> `Status.InvalidArgument`: the generated vocabulary's own spelling of a status name. */
function statusOf(name: string): number | undefined {
  const key = name
    .replace(/^CHS_/, '')
    .toLowerCase()
    .replace(/(^|_)([a-z])/g, (_m: string, _sep: string, c: string) => c.toUpperCase());
  return (Status as Readonly<Record<string, number>>)[key];
}

/** What differs between a step's outcome and its expectation; '' when none. */
function outcome(want: Expect, error: unknown): string {
  if (want.ok === true) return error === undefined ? '' : `want success, got ${String(error)}`;
  const cls = want.class === undefined ? undefined : CLASSES[want.class];
  if (cls === undefined) return `the case names an error class this runner does not know: ${String(want.class)}`;
  if (!(error instanceof cls)) return `want ${cls.name}, got ${error === undefined ? 'success' : String(error)}`;
  const e = error as unknown as { status: number; chCode: number; chName: string };
  if (want.status !== undefined) {
    const status = statusOf(want.status);
    if (status === undefined) return `the case names a status this binding does not know: ${want.status}`;
    if (e.status !== status) return `status ${e.status}, want ${want.status}`;
  }
  if (want.ch_code !== undefined && e.chCode !== want.ch_code) return `ch_code ${e.chCode}, want ${want.ch_code}`;
  if (want.ch_name !== undefined && e.chName !== want.ch_name) return `ch_name ${e.chName}, want ${want.ch_name}`;
  const reason = (error as { reason?: unknown }).reason;
  if (want.reason !== undefined && reason !== want.reason) return `reason ${String(reason)}, want ${want.reason}`;
  return '';
}

describe('the setup cases file', () => {
  it('is not empty: a suite that ran nothing must not pass', () => {
    expect(setupCases.length).toBeGreaterThan(0);
  });
});

describe.skipIf(!stubsAvailable)('the shared setup cases, through the public API', () => {
  it.each(setupCases.map((c) => [c.id, c] as const))('%s', async (_id, c) => {
    expect(c.steps.length).toBeGreaterThan(0);
    const why = c.not_expressible?.ts;
    if (why !== undefined) {
      console.info(`SKIPPED (loudly): ${c.id} is not expressible in TypeScript: ${why}`);
      return;
    }
    const dir = mkdtempSync(path.join(os.tmpdir(), 'setup-case-'));
    const images = new Map<string, string>();
    /** The case's one fresh copy of `variant` (the case's own by default). */
    const image = (variant: string | undefined): string => {
      const v = variant ?? c.variant;
      let copy = images.get(v);
      if (copy === undefined) {
        copy = path.join(dir, `${v}-image.so`);
        copyFileSync(path.join(STUBS_DIR as string, `${v}.so`), copy);
        chmodSync(copy, 0o755);
        images.set(v, copy);
      }
      return copy;
    };
    // The case's open library, and the schemas and filters its steps (rule r7) name.
    let current: Library | undefined;
    const schemas = new Map<string, Schema>();
    const filters = new Map<string, Filter>();
    let batchRowsPassed: number | undefined;
    resetSetupForTests();
    const saved = process.env.CHTYPES_ALLOW_UNVERIFIED_LIBRARY;
    const warn = vi.spyOn(console, 'warn').mockImplementation(() => {});
    process.env.CHTYPES_ALLOW_UNVERIFIED_LIBRARY = '1';
    try {
      for (const [i, step] of c.steps.entries()) {
        let error: unknown;
        let opened: Library | undefined;
        if (step.op === 'filter_close') {
          (filters.get(step.filter as string) as Filter).close();
          continue;
        }
        try {
          if (step.op === 'filter_new') {
            filters.set(step.as as string, (schemas.get(step.schema as string) as Schema).compileFilter(step.expression as string));
          } else if (step.op === 'rows') {
            batchRowsPassed = undefined;
            const rowFilter = step.filter === undefined ? undefined : filters.get(step.filter);
            const batch = (schemas.get(step.schema as string) as Schema).rows(Format.CSV, Buffer.from(step.body as string), { rowFilter });
            batchRowsPassed = batch.rowsPassed;
          } else if (step.op === 'compile') {
            schemas.set(step.as as string, (current as Library).compileTable(step.statement as string));
          } else if (step.op === 'setup') setup({ timezone: step.timezone ?? '' });
          else if (step.op === 'open' && step.request !== undefined) {
            // A registry over an empty cache, offline, autofetch off.
            const cacheDir = mkdtempSync(path.join(dir, 'cache-'));
            const registry = await Registry.open({ fetch: { cacheDir, systemDirs: [], offline: true }, autofetch: false });
            opened = await registry.for(step.request);
          } else if (step.op === 'open') opened = openUnverified(image(step.variant), { allow: step.allow ?? true });
          else throw new Error(`step ${i}: an op this runner does not know: ${step.op}`);
        } catch (err) {
          const known = Object.values(CLASSES).some((cls) => err instanceof cls);
          if (!known) throw err;
          error = err;
        }
        if (opened !== undefined) current = opened;
        let diff = outcome(step.expect, error);
        if (diff === '' && step.rows_passed !== undefined && step.rows_passed !== batchRowsPassed) {
          diff = `rows_passed ${String(batchRowsPassed)}, want ${step.rows_passed}: the stub says whether the filter reached the library`;
        }
        if (diff === '' && step.expect.image_zone !== undefined) {
          const zone = (opened as Library).validateType(setupDoc.image_zone_probe).toString('utf8');
          if (zone !== step.expect.image_zone) diff = `the image was set up with zone ${JSON.stringify(zone)}, want ${JSON.stringify(step.expect.image_zone)}`;
        }
        expect(diff, `step ${i} (${step.op} ${JSON.stringify(step.timezone ?? '')} ${step.variant ?? ''}${step.request ?? ''})`).toBe('');
      }
    } finally {
      warn.mockRestore();
      resetSetupForTests();
      if (saved === undefined) delete process.env.CHTYPES_ALLOW_UNVERIFIED_LIBRARY;
      else process.env.CHTYPES_ALLOW_UNVERIFIED_LIBRARY = saved;
    }
  });
});
